), novos as (
  select case when d.micro then 'kitsMicro' else 'kitsInversor' end categoria,
         case when d.micro then format('KIT %s MOD. %sW + MICROINVERSOR HOYMILES 2,25KW', d.n, d.w)
              else format('KIT %s MOD. %sW + INV. %s', d.n, d.w, i.curto) end name,
         d.kwp power, d.price, d.list_price,
         case when not d.micro and d.n > md.lim_mono then 'Trifásico' else 'Bifásico' end type,
         case when d.micro then format('%s módulos %s de %sW e %s microinversor%s HOYMILES 2,25KW', d.n, md.marca, d.w, d.q, case when d.q > 1 then 'es' else '' end)
              else format('%s módulos %s de %sW e INVERSOR %s | %s', d.n, md.marca, d.w, i.curto, case when d.n > md.lim_mono then 'trifásico 220 V' else '220 V' end) end description,
         md.id modulo_id, d.n modulo_qtd, i.id inversor_id, d.q inversor_qtd, d.custo,
         jsonb_build_object('data', '2026-10-13', 'pecas', d.pecas, 'frete', d.custo - d.pecas, 'cabo', 4.25, 'inversor', i.curto,
                            'modulo', d.w || 'W', 'estrutura', case when d.w = 710 then 'ANGULO SMART' else 'ANGULO STANDARD' end) detalhe
  from d join inv i on i.hid = d.hid join md on md.w = d.w
), ins as (
  insert into produtos (categoria, name, brand, power, price, list_price, type, tag, description, franquia_id, ativo,
                        modulo_id, modulo_qtd, inversor_id, inversor_qtd, distribuidora_id, linha)
  select n.categoria, n.name, 'MÓDULOS N-TYPE', n.power, n.price, n.list_price, n.type, 'MAIS VENDIDO', n.description,
         'af146be2-1489-4ad0-82f8-802b9dec5b6b', true, n.modulo_id, n.modulo_qtd, n.inversor_id, n.inversor_qtd, '23a51365-a37f-444c-9c45-22645515f2cc', 'catalogo'
  from novos n where not exists (select 1 from produtos p where p.name = n.name)
  returning id, name, price, list_price
), pf as (
  insert into precos_franquia (produto_id, franquia_id, price, list_price)
  select i.id, 'af146be2-1489-4ad0-82f8-802b9dec5b6b', i.price, i.list_price from ins i
  returning produto_id
)
insert into produtos_custo (produto_id, custo, fonte, detalhe)
select i.id, n.custo, 'helte', n.detalhe from ins i join novos n on n.name = i.name;
